const MAP = "plans/row.justify.json";

/** `pnpm ui-facts --plan` or `--prove` through the CLI entry: the exit code and what it printed. */
function migrate(root: string, mode: "plan" | "prove"): { readonly code: number; readonly printed: string } {
  const printed: string[] = [];
  const write = vi.spyOn(process.stdout, "write").mockImplementation((chunk) => {
    printed.push(String(chunk));
    return true;
  });
  try {
    return { code: runUiFacts([`--root=${root}`, "--out=census", `--${mode}=row.justify`, `--map=${MAP}`]), printed: printed.join("") };
  } finally {
    write.mockRestore();
  }
}

const planOf = (root: string): MigrationPlan => JSON.parse(readFileSync(join(root, MAP), "utf8")) as MigrationPlan;

const MIGRATING = [
  'import { Row, Row as Line } from "@orb/ui/layout";',
  "export const A = ({ open }: { open: boolean }) => (",
  "  <>",
  '    <Row className="justify-end" />',
  '    <Line className="justify-end x" />',
  '    <Row className="justify-between" />',
  '    <Row className={open ? "justify-end" : undefined} />',
  '    <Track of={Row} className="justify-end" />',
  "  </>",
  ");",
].join("\n");

test("a plan lists a row only when the arm writes exactly its class on a named component, and sends every other row to review", ({ scratch }) => {
  const root = plantDir(scratch, "migration-plan");
  plant(root, { "components/uses.tsx": MIGRATING });
  const { code, printed } = migrate(root, "plan");
  const plan = planOf(root);
  expect(code).toBe(0);
  expect(printed).toContain("planned row.justify: 2 sites in 1 files, 2 for review");
  // The alias is planned under the name its import exports, with the specifier a rewrite must prove.
  expect(plan.sites.map(({ line, source, name, token, prop, value }) => [line, source, name, token, prop, value])).toEqual([
    [4, "@orb/ui/layout", "Row", "justify-end", "justify", "end"],
    [5, "@orb/ui/layout", "Row", "justify-end", "justify", "end"],
  ]);
  // The conditional site is a different owner and never appears; the arm that writes two classes and the carrier go to review.
  expect(plan.review.map(({ line, reason }) => [line, reason])).toEqual([
    [6, 'arm "between" writes justify-between items-baseline, which is not exactly justify-between'],
    [8, "the class is written on a carrier that renders Row"],
  ]);
});

test("a proof passes when every remaining row has a reason, and fails on a row nothing explains", ({ scratch }) => {
  const root = plantDir(scratch, "migration-proof");
  plant(root, { "components/uses.tsx": MIGRATING });
  migrate(root, "plan");
  // The rewrite's result: the planned classes moved onto the prop; the two reviewed rows and the conditional one are as they were.
  plant(root, {
    "components/uses.tsx": MIGRATING.replace('<Row className="justify-end" />', '<Row justify="end" />').replace(
      '<Line className="justify-end x" />',
      '<Line className="x" justify="end" />',
    ),
  });
  expect(migrate(root, "prove")).toMatchObject({ code: 0 });
  expect(migrate(root, "prove").printed).toContain("2 remain, 0 without a reason");
  // A row the plan listed and the codemod skipped is explained only by the skip it recorded.
  plant(root, { "components/uses.tsx": MIGRATING });
  const unexplained = migrate(root, "prove");
  expect(unexplained.code).toBe(1);
  expect(unexplained.printed).toContain("no reason: packages/client/src/features/probe/components/uses.tsx:4 justify-end");
  plantFile(
    root,
    "plans/row.justify.skips/packages__client__src__features__probe__components__uses.tsx.json",
    JSON.stringify([
      { path: "packages/client/src/features/probe/components/uses.tsx", line: 4, token: "justify-end", reason: "unproven: Row is not an import" },
      { path: "packages/client/src/features/probe/components/uses.tsx", line: 5, token: "justify-end", reason: "unproven: Line is not an import" },
    ]),
  );
  expect(migrate(root, "prove")).toMatchObject({ code: 0 });
});
